import{_ as e,o,c as a,ag as r}from"./chunks/framework.BuUvxvtQ.js";const p=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"web-app/getting-started.md","filePath":"web-app/getting-started.md"}'),s={name:"web-app/getting-started.md"};function n(i,t,l,d,h,c){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>New to Sky Style? This walkthrough takes you from sign-up to your first refined recommendation in a few minutes.</p><h2 id="step-1-—-create-an-account" tabindex="-1">Step 1 — Create an account <a class="header-anchor" href="#step-1-—-create-an-account" aria-label="Permalink to &quot;Step 1 — Create an account&quot;">​</a></h2><ol><li>Go to <a href="https://skystyle.app" target="_blank" rel="noreferrer">skystyle.app</a>.</li><li>Click <strong>Get started free</strong> (or <strong>Try Live Demo</strong> to preview weather data without an account).</li><li>Sign in with <strong>GitHub</strong> or <strong>Google</strong>.</li></ol><p>You start on the <strong>Free</strong> plan: 20 AI recommendations, 40 follow-ups, and 4 closet uses per day. See <a href="./account-and-support.html#plans">Plans</a>.</p><h2 id="step-2-—-take-the-dashboard-tour" tabindex="-1">Step 2 — Take the dashboard tour <a class="header-anchor" href="#step-2-—-take-the-dashboard-tour" aria-label="Permalink to &quot;Step 2 — Take the dashboard tour&quot;">​</a></h2><p>On your first visit to the dashboard, a guided tour appears automatically. It has three steps:</p><ol><li><strong>Choose a location</strong> — use the weather panel to enter a location or use GPS.</li><li><strong>Set your preferences</strong> — adjust planning and closet options before generating an outfit.</li><li><strong>Continue the conversation</strong> — use follow-ups to refine an outfit once it is ready.</li></ol><p>You can <strong>replay the tour</strong> anytime from <a href="./settings.html#tutorials">Settings → Tutorials</a>.</p><h2 id="step-3-—-pick-a-location" tabindex="-1">Step 3 — Pick a location <a class="header-anchor" href="#step-3-—-pick-a-location" aria-label="Permalink to &quot;Step 3 — Pick a location&quot;">​</a></h2><p>On the dashboard&#39;s weather panel:</p><ul><li>Click <strong>Use my location</strong> to grant GPS access for the most accurate local weather, <strong>or</strong></li><li>Type a city or place name into the search box and pick from the matches (geocoded via OpenStreetMap).</li></ul><p>Your location consent is controlled in <a href="./settings.html#preferences">Settings → Preferences</a>. If you don&#39;t consent to sharing your location with the AI, Sky Style still fetches weather for your coordinates but won&#39;t include your location text in the AI prompt.</p><h2 id="step-4-—-generate-your-first-recommendation" tabindex="-1">Step 4 — Generate your first recommendation <a class="header-anchor" href="#step-4-—-generate-your-first-recommendation" aria-label="Permalink to &quot;Step 4 — Generate your first recommendation&quot;">​</a></h2><ol><li>(Optional) Choose a <strong>recommendation mode</strong> in the Weather Planning panel: Simple, Simple+, Advanced, or Pro. Simple is fine to start.</li><li>Click <strong>Generate</strong> (or the equivalent action on the panel).</li><li>Sky Style fetches weather, builds a prompt, and calls the AI. You&#39;ll see the outfit, the reasoning, and the weather used.</li></ol><div class="tip custom-block"><p class="custom-block-title">What you&#39;ll see</p><p>The result includes the <strong>outfit</strong> (concise text), <strong>reasoning</strong> (why those choices suit the weather), the <strong>weather snapshot</strong> used, and the <strong>model</strong> that generated it.</p></div><h2 id="step-5-—-ask-a-follow-up" tabindex="-1">Step 5 — Ask a follow-up <a class="header-anchor" href="#step-5-—-ask-a-follow-up" aria-label="Permalink to &quot;Step 5 — Ask a follow-up&quot;">​</a></h2><p>Refine the recommendation by asking a follow-up question — for example:</p><ul><li>&quot;Should I bring an umbrella?&quot;</li><li>&quot;What if I need formal shoes?&quot;</li><li>&quot;It&#39;s for an outdoor wedding — how should I adjust?&quot;</li></ul><p>Follow-ups run in one of two modes (<a href="./settings.html#dashboard-behaviour">set in Settings</a>):</p><ul><li><strong>Replace mode</strong> — the follow-up overwrites the current outfit.</li><li><strong>Chat mode</strong> — follow-ups stack below, keeping a conversation.</li></ul><p>You have <strong>40 follow-ups per day</strong> on the Free plan.</p><h2 id="step-6-—-add-clothes-to-your-closet" tabindex="-1">Step 6 — Add clothes to your closet <a class="header-anchor" href="#step-6-—-add-clothes-to-your-closet" aria-label="Permalink to &quot;Step 6 — Add clothes to your closet&quot;">​</a></h2><p>So recommendations match what you actually own:</p><ol><li>Open the <strong>Closet</strong> page (<code>/closet</code>) from the navigation.</li><li>Add items (e.g. &quot;White Oxford shirt&quot;, &quot;Navy chinos&quot;, &quot;Black Chelsea boots&quot;).</li><li>Future recommendations can reference your closet items.</li></ol><p>Closet usage is limited to <strong>4 uses per day</strong> on the Free plan (the closet panel can be opened from the dashboard too).</p><h2 id="step-7-—-explore-your-account" tabindex="-1">Step 7 — Explore your account <a class="header-anchor" href="#step-7-—-explore-your-account" aria-label="Permalink to &quot;Step 7 — Explore your account&quot;">​</a></h2><ul><li><strong><a href="./settings.html">Settings</a></strong> — set your gender context, units, theme, and dashboard behaviour.</li><li><strong><a href="./security-and-privacy.html">Security &amp; Privacy</a></strong> — enable 2FA, add a passkey, or manage your data.</li><li><strong><a href="./account-and-support.html">Account</a></strong> — view your plan, usage, and credits.</li><li><strong><a href="./automatic-recommendations.html">Automatic Recommendations</a></strong> — schedule a recommendation for a specific time.</li></ul><h2 id="daily-limits-at-a-glance" tabindex="-1">Daily limits at a glance <a class="header-anchor" href="#daily-limits-at-a-glance" aria-label="Permalink to &quot;Daily limits at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Counter</th><th>Free</th><th>Resets</th></tr></thead><tbody><tr><td>AI recommendations</td><td>20/day</td><td>Midnight UTC</td></tr><tr><td>Follow-ups</td><td>40/day</td><td>Midnight UTC</td></tr><tr><td>Closet uses</td><td>4/day</td><td>Midnight UTC</td></tr><tr><td>Source picks</td><td>4/day</td><td>Midnight UTC</td></tr><tr><td>Model switches</td><td>2/day</td><td>Midnight UTC</td></tr></tbody></table><p>When you approach a limit, the dashboard shows your usage. See <a href="./how-it-works.html#usage-limits">How It Works → Usage limits</a> for the full table across plans.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><strong><a href="./how-it-works.html">How It Works</a></strong> — understand the weather sources, AI models, and the full flow.</li><li><strong><a href="./dashboard.html">Dashboard &amp; Closet</a></strong> — detailed reference for every dashboard feature.</li><li><strong><a href="./faq.html">FAQ &amp; Troubleshooting</a></strong> — common questions and fixes.</li></ul>',33)])])}const g=e(s,[["render",n]]);export{p as __pageData,g as default};
